-- 1. 赛事信息（BWF）
with match_info as (
  select distinct
    day as dt,
    uid as luid,
    match_name
  from zhgametemp.hss_huya_sport_movie_liveroom_register_info_d_a
  where 
    dt = '2026-07-01'
    and day >= '2024-01-01' 
    and day <= '2026-06-30'
    and match_name like '%BWF%'
    and uid in (
      1447756350,1239543865786,1239543865782,1239543865783,1239543865784,1239543865785,1099531627925,1099531728575,1099531728616,1099531728624,1239543865809,1239543865810,1239543865811,1239543865812,1239543865813,1239543865814,1239543865867,1239543865868,1239543865869,1239543865870,1099531840904,1239543865871,1239543865850,1239543865851,1239543865852,1239543865853,1239543865791,1239543865816,1239543151710,1239543865787,1239543865788,1239543865793,1239543865794,1239543865795,1239543865796,1239543865797,1239543865798,1239543865800,1239543865801,1239543865802,1239543865803,1239543865804,1199656263863,1199597387673,1199521065754,1199656255873,1199656182930,1279540076357,1279521573145,1199654006345,1199656302044,1199656295593,1199656295679,1199656310785,1199656288532,1199656352391,1199656261631,1279548551974,1199656426238,1199656674508,1753825805,1199652717090,2373515260,1199656702936,1279516600687,1673079837,1199634593987,1199599175963,1677421524,1199642045234,1279532267906,1199600383157,2282482639,1199639452798,1199647949332,1199640786635,1486343265,1199590843647,1697742438,1199660738266,1636189397,1199656763692,1199656742112,1199656773367,1199641717022,1199656429498,1199533419858,1199658089096,2292755394,1199658062453,1199624278883,1279548684292,1199530610655,1199658188643,1588496380,1199658186849,1199658193452,1862108531,1199658183128,1259525220200,1689405589,1199620517110,1199658189598,1199658201944,1199643044995,1199658177568,1199658218275,1199547503910,1199658233170,2333307226,1199658522269,1199658103297,1279544695402,1199597881340,1279548768696,1279548744563,1259527226795,1199660936940,1199644384755,1199656355067,1239544181881,1279519921995,1199550713938,1279548681487,1199661105760,1199660939339,1199660925502,1199529235589,1199661142965,1199661208181,1199661244528,1199656219118,1199661242484,1199661278327,1279548912765,1199550364425,1259589498582,1199656878808,1199662930460,1199662973428,1199660246832,1199647041101,1734613359,1199661311607,1199652916449,1199663198331,1199663573610,1199625885290,1199663597241,1607012848,1199661077059,1199656673216,1177750072,1199659092546,1199657274878,1279524559633,1199664767493,1239543827882,1239543827883,1199664870387,1279524145476,1199662132485,1199665001470,1199664991522,1199639691667,1199665096643,1199665047879,1199665100593,1199665113441,1199656401051,1199640884636,2310549735,1199658173384,1199665325098
    )
),

laxin_user_info as (
  select distinct
    b.dt,
    b.label,
    b.user_ukey
  from match_info a
  inner join (
      select 
        dt, 
        luid, 
        user_ukey,
        '拉新' as label
      from zhgametemp.new_user_neirong_laxin_with_shichang_ukey_v1
      where dt between '2025-06-01' and '2026-06-30'
        -- and user_product in ('huya_andriod','huya_ipad','huya_pad','huya_ios','hmos_kiwi')

      union all 

      
      select distinct 
        dt,
        luid,
        user_ukey,
        '回流' as tag
      from zhgametemp.huiliu_user_neirong_with_shichang_ukey_v1
      where dt between '2025-06-01' and '2026-06-30'
  ) b 
  on a.dt = b.dt and a.luid = b.luid
)

select
  date_trunc('month', dt) as mth,
  count(distinct user_ukey) as laxin_huiliu_user_cnt,
  count(distinct case when label = '拉新' then user_ukey end )  as laxin_user_cnt,
  count(distinct case when label = '回流' then user_ukey end )  as huiliu_user_cnt,
  count(distinct user_ukey)/count(distinct dt) as avg_laxin_huiliu_user_cnt,
  count(distinct case when label = '拉新' then user_ukey end )/count(distinct dt) as avg_laxin_user_cnt,
  count(distinct case when label = '回流' then user_ukey end )/count(distinct dt) as avg_huiliu_user_cnt
from laxin_user_info
group by date_trunc('month', dt)